apiVersion: gateway.networking.k8s.io/v1
kind: Gateway
metadata: {name: prod-gw, namespace: gateway}
spec:
  gatewayClassName: envoy-gateway    # 对应 GatewayClass
  listeners:
  - name: http
    port: 80
    protocol: HTTP
    allowedRoutes: {namespaces: {from: All}}
  - name: https
    port: 443
    protocol: HTTPS
    tls: {mode: Terminate, certificateRefs: [{group: "", kind: Secret, name: web-tls}]}
    allowedRoutes: {namespaces: {from: All}}

---
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata: {name: api, namespace: app}
spec:
  parentRefs:
  - {name: prod-gw, namespace: gateway}
  hostnames: [api.example.com]
  rules:
  - matches:
    - {path: {type: PathPrefix, value: /v2}}
    filters:
    - {type: RequestHeaderModifier, requestHeaderModifier:
        {set: [{name: X-Route-Source, value: gateway-api}]}}
    backendRefs:
    - {name: api-v2, port: 80, weight: 90}
    - {name: api-v1, port: 80, weight: 10}
  - matches:
    - headers: [{type: Exact, name: X-Canary, value: "true"}]
    backendRefs: [{name: api-v2, port: 80, weight: 1}]

---
# 跨命名空间引用的显式授权
apiVersion: gateway.networking.k8s.io/v1beta1
kind: ReferenceGrant
metadata: {name: allow-routes, namespace: backend}
spec:
  from:
  - {group: gateway.networking.k8s.io, kind: HTTPRoute, namespace: app}
  to:
  - {group: "", kind: Service}

apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: web-default-deny-then-allow
  namespace: prod
spec:
  podSelector:
    matchLabels: {app: web}
  policyTypes: [Ingress, Egress]
  ingress:
  - from:                          # 一个列表项 = AND：gateway ns 里带 app=gateway 标签的 Pod
    - namespaceSelector:
        matchLabels: {kubernetes.io/metadata.name: gateway}
      podSelector:
        matchLabels: {app: gateway}
    ports:
    - {protocol: TCP, port: 8080}
  egress:
  - to:                            # 1) 先放 DNS，否则全断（G21 前置知识）
    - namespaceSelector:
        matchLabels: {kubernetes.io/metadata.name: kube-system}
      podSelector:
        matchLabels: {k8s-app: kube-dns}
    ports:
    - {protocol: UDP, port: 53}
    - {protocol: TCP, port: 53}
  - to:                            # 2) 再放业务依赖
    - podSelector: {matchLabels: {app: db}}
    ports:
    - {protocol: TCP, port: 5432}

// xdp_drop.c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
SEC("xdp")
int xdp_drop(struct xdp_md *ctx) {
    return XDP_DROP;   // 驱动层直接丢弃：可用于临时封禁源 IP（授权的防御场景）
}
